import { ChevronDown, CircleAlert, CircleCheck } from 'lucide-react'
import * as React from 'react'
import { useId, useState } from 'react'

import { cx } from '~/lib/cx'

import styles from './floating-label-input.module.scss'

/**
 * Floating-label fields.
 *
 * The label starts as a placeholder inside the control and glides to the
 * top-left when the field is focused or filled. Float state is driven by CSS
 * (`:focus` + `:not(:placeholder-shown)`) so browser autofill and controlled
 * values both work without JS. `placeholder` is reserved for the CSS probe —
 * put format guidance in `hint` instead.
 */

export type FloatingVariant = 'filled' | 'outlined' | 'underline'
export type FloatingSize = 'sm' | 'md' | 'lg'

const FRAME_VARIANT: Record<FloatingVariant, string> = {
  filled: styles.filled,
  outlined: styles.outlined,
  underline: styles.underline,
}

const FRAME_SIZE: Record<FloatingSize, string> = {
  sm: styles.sm,
  md: styles.md,
  lg: styles.lg,
}

export interface FloatingFieldBaseProps {
  label: string
  /** Helper text under the field. Hidden while `error` or `success` shows. */
  hint?: string
  error?: string
  success?: string
  required?: boolean
  variant?: FloatingVariant
  size?: FloatingSize
  leading?: React.ReactNode
  trailing?: React.ReactNode
  /** Force the floated state (e.g. `type="date"` or a custom control). */
  filled?: boolean
  /**
   * Colour behind the outlined notch. Defaults to the page background.
   * Pass `hsl(var(--card))` when the field sits on a card.
   */
  notchBg?: string
  wrapClassName?: string
}

function FieldMessage({
  hint,
  error,
  success,
  hintId,
  errorId,
  successId,
}: {
  hint?: string
  error?: string
  success?: string
  hintId: string
  errorId: string
  successId: string
}) {
  if (error) {
    return (
      <p id={errorId} role="alert" className={cx(styles.message, styles.errorText)}>
        <CircleAlert className={styles.messageIcon} aria-hidden />
        <span>{error}</span>
      </p>
    )
  }
  if (success) {
    return (
      <p id={successId} className={cx(styles.message, styles.successText)}>
        <CircleCheck className={styles.messageIcon} aria-hidden />
        <span>{success}</span>
      </p>
    )
  }
  if (hint) {
    return (
      <p id={hintId} className={styles.hint}>
        {hint}
      </p>
    )
  }
  return null
}

function FieldShell({
  label,
  hint,
  error,
  success,
  required,
  variant = 'filled',
  size = 'md',
  leading,
  trailing,
  filled,
  notchBg,
  wrapClassName,
  id,
  children,
  multiline = false,
  chevron = false,
  disabled,
}: FloatingFieldBaseProps & {
  id: string
  children: React.ReactNode
  multiline?: boolean
  chevron?: boolean
  disabled?: boolean
}) {
  const hintId = `${id}-hint`
  const errorId = `${id}-error`
  const successId = `${id}-success`
  const hasError = Boolean(error)
  const hasSuccess = Boolean(success) && !hasError
  const hasLeading = leading != null
  const hasTrailing = trailing != null || chevron

  return (
    <div className={cx(styles.root, wrapClassName)}>
      <div
        data-filled={filled ? 'true' : undefined}
        data-invalid={hasError ? 'true' : undefined}
        style={
          notchBg
            ? ({ '--vz-float-notch': notchBg } as React.CSSProperties)
            : undefined
        }
        className={cx(
          styles.frame,
          FRAME_VARIANT[variant],
          FRAME_SIZE[size],
          hasError && styles.invalid,
          hasSuccess && styles.valid,
          disabled && styles.disabled,
        )}
      >
        {hasLeading ? (
          <span className={styles.leading} aria-hidden>
            {leading}
          </span>
        ) : null}

        <div className={styles.controlWrap}>
          {children}
          <label
            htmlFor={id}
            className={cx(
              styles.label,
              hasLeading && styles.labelLeading,
              multiline && styles.labelMultiline,
            )}
          >
            {label}
            {required ? (
              <>
                <span className={styles.required} aria-hidden>
                  *
                </span>
                <span className={styles.srOnly}> (required)</span>
              </>
            ) : null}
          </label>
        </div>

        {hasTrailing ? (
          <span className={styles.trailing}>
            {trailing ?? <ChevronDown className={styles.chevronIcon} aria-hidden />}
          </span>
        ) : null}
      </div>

      <FieldMessage
        hint={hint}
        error={error}
        success={success}
        hintId={hintId}
        errorId={errorId}
        successId={successId}
      />
    </div>
  )
}

export interface FloatingLabelInputProps
  extends FloatingFieldBaseProps,
    Omit<React.ComponentPropsWithoutRef<'input'>, 'placeholder' | 'size'> {}

export const FloatingLabelInput = React.forwardRef<
  HTMLInputElement,
  FloatingLabelInputProps
>(function FloatingLabelInput(
  {
    label,
    hint,
    error,
    success,
    required,
    variant = 'filled',
    size = 'md',
    leading,
    trailing,
    filled,
    notchBg,
    wrapClassName,
    className,
    id: idProp,
    disabled,
    ...props
  },
  ref,
) {
  const generatedId = useId()
  const id = idProp ?? generatedId
  const hasError = Boolean(error)

  return (
    <FieldShell
      label={label}
      hint={hint}
      error={error}
      success={success}
      required={required}
      variant={variant}
      size={size}
      leading={leading}
      trailing={trailing}
      filled={filled}
      notchBg={notchBg}
      wrapClassName={wrapClassName}
      id={id}
      disabled={disabled}
    >
      <input
        ref={ref}
        id={id}
        placeholder=" "
        required={required}
        disabled={disabled}
        aria-invalid={hasError || undefined}
        aria-describedby={
          error
            ? `${id}-error`
            : success
              ? `${id}-success`
              : hint
                ? `${id}-hint`
                : undefined
        }
        className={cx(
          styles.control,
          styles.input,
          leading && styles.withLeading,
          trailing && styles.withTrailing,
          className,
        )}
        {...props}
      />
    </FieldShell>
  )
})

export interface FloatingLabelTextareaProps
  extends FloatingFieldBaseProps,
    Omit<React.ComponentPropsWithoutRef<'textarea'>, 'placeholder'> {}

export const FloatingLabelTextarea = React.forwardRef<
  HTMLTextAreaElement,
  FloatingLabelTextareaProps
>(function FloatingLabelTextarea(
  {
    label,
    hint,
    error,
    success,
    required,
    variant = 'filled',
    size = 'md',
    leading,
    trailing,
    filled,
    notchBg,
    wrapClassName,
    className,
    id: idProp,
    disabled,
    rows = 4,
    ...props
  },
  ref,
) {
  const generatedId = useId()
  const id = idProp ?? generatedId
  const hasError = Boolean(error)

  return (
    <FieldShell
      label={label}
      hint={hint}
      error={error}
      success={success}
      required={required}
      variant={variant}
      size={size}
      leading={leading}
      trailing={trailing}
      filled={filled}
      notchBg={notchBg}
      wrapClassName={wrapClassName}
      id={id}
      multiline
      disabled={disabled}
    >
      <textarea
        ref={ref}
        id={id}
        rows={rows}
        placeholder=" "
        required={required}
        disabled={disabled}
        aria-invalid={hasError || undefined}
        aria-describedby={
          error
            ? `${id}-error`
            : success
              ? `${id}-success`
              : hint
                ? `${id}-hint`
                : undefined
        }
        className={cx(
          styles.control,
          styles.textarea,
          leading && styles.withLeading,
          trailing && styles.withTrailing,
          className,
        )}
        {...props}
      />
    </FieldShell>
  )
})

export interface FloatingLabelSelectProps
  extends FloatingFieldBaseProps,
    Omit<React.ComponentPropsWithoutRef<'select'>, 'size' | 'placeholder'> {}

export const FloatingLabelSelect = React.forwardRef<
  HTMLSelectElement,
  FloatingLabelSelectProps
>(function FloatingLabelSelect(
  {
    label,
    hint,
    error,
    success,
    required,
    variant = 'filled',
    size = 'md',
    leading,
    trailing,
    filled,
    notchBg,
    wrapClassName,
    className,
    id: idProp,
    disabled,
    value,
    defaultValue,
    onChange,
    ...props
  },
  ref,
) {
  const generatedId = useId()
  const id = idProp ?? generatedId
  const hasError = Boolean(error)
  const [internal, setInternal] = useState(() =>
    defaultValue == null ? '' : String(defaultValue),
  )
  const current = value == null ? internal : String(value)
  const isFilled = Boolean(filled) || current.length > 0

  return (
    <FieldShell
      label={label}
      hint={hint}
      error={error}
      success={success}
      required={required}
      variant={variant}
      size={size}
      leading={leading}
      trailing={trailing}
      filled={isFilled}
      notchBg={notchBg}
      wrapClassName={wrapClassName}
      id={id}
      chevron={trailing == null}
      disabled={disabled}
    >
      <select
        ref={ref}
        id={id}
        {...(value === undefined ? { defaultValue } : { value })}
        required={required}
        disabled={disabled}
        aria-invalid={hasError || undefined}
        aria-describedby={
          error
            ? `${id}-error`
            : success
              ? `${id}-success`
              : hint
                ? `${id}-hint`
                : undefined
        }
        onChange={(event) => {
          setInternal(event.target.value)
          onChange?.(event)
        }}
        className={cx(
          styles.control,
          styles.select,
          leading && styles.withLeading,
          className,
        )}
        {...props}
      />
    </FieldShell>
  )
})

@use 'styles' as vz;

.root {
  display: flex;
  flex-direction: column;
  gap: vz.space(1.5);
  width: 100%;
  min-width: 0;
}

.frame {
  position: relative;
  display: flex;
  align-items: stretch;
  width: 100%;
  min-height: var(--frame-min);
  border-radius: vz.radius('lg');
  color: vz.color('foreground');
  transition:
    background-color vz.duration('base') vz.ease('out'),
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.filled {
  --label-float-top: #{vz.space(1.5)};
  --label-float-y: 0;

  border: 1px solid transparent;
  background: vz.color('secondary', 0.7);

  @include vz.hover {
    background: vz.color('secondary');
  }

  &:focus-within {
    background: vz.color('secondary');
    box-shadow: 0 0 0 2px vz.color('ring', 0.3);
  }
}

.outlined {
  --label-float-top: 0;
  --label-float-y: -0.375rem;

  border: 1px solid vz.color('input');
  background: transparent;

  &:focus-within {
    border-color: vz.color('ring');
    box-shadow: 0 0 0 2px vz.color('ring', 0.2);
  }
}

.underline {
  --label-float-top: #{vz.space(1.5)};
  --label-float-y: 0;

  border: 0;
  border-bottom: 2px solid vz.color('input');
  border-radius: 0;
  background: transparent;

  &:focus-within {
    border-bottom-color: vz.color('ring');
  }
}

.sm {
  --frame-min: #{vz.space(12)};
  --control-pt: #{vz.space(5)};
  --control-pb: #{vz.space(1)};
}

.md {
  --frame-min: #{vz.space(14)};
  --control-pt: #{vz.space(6)};
  --control-pb: #{vz.space(2)};
}

.lg {
  --frame-min: #{vz.space(16)};
  --control-pt: #{vz.space(7)};
  --control-pb: #{vz.space(3)};
}

.invalid {
  border-color: vz.color('destructive');

  &:focus-within {
    border-color: vz.color('destructive');
    box-shadow: 0 0 0 2px vz.color('destructive', 0.25);
  }
}

.valid {
  border-color: vz.color('success', 0.7);

  &:focus-within {
    border-color: vz.color('success');
    box-shadow: 0 0 0 2px vz.color('success', 0.2);
  }
}

.disabled {
  opacity: 0.6;
  pointer-events: none;
}

.leading {
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: vz.space(10);
  color: vz.color('muted-foreground');
  pointer-events: none;

  svg {
    @include vz.icon(4);
  }
}

.trailing {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  width: vz.space(10);
  color: vz.color('muted-foreground');

  button {
    pointer-events: auto;
  }

  svg {
    @include vz.icon(4);
  }
}

.chevron-icon {
  @include vz.icon(4);
}

.control-wrap {
  position: relative;
  flex: 1;
  min-width: 0;
}

.control {
  width: 100%;
  height: 100%;
  min-width: 0;
  padding-block: var(--control-pt) var(--control-pb);
  padding-inline: vz.space(3.5);
  border: 0;
  background: transparent;
  color: vz.color('foreground');
  font-family: inherit;
  font-size: vz.font-size('base');
  font-weight: 400;
  caret-color: vz.color('foreground');
  outline: none;

  &::placeholder {
    color: transparent;
  }

  @include vz.disabled {
    cursor: not-allowed;
  }
}

.input {
  appearance: none;
}

.with-leading {
  padding-inline-start: vz.space(10);
}

.with-trailing {
  padding-inline-end: vz.space(10);
}

.outlined .control {
  padding-block: 0;
}

.textarea {
  min-height: 7rem;
  padding-block: vz.space(8) vz.space(3);
  resize: vertical;
}

.outlined .textarea {
  padding-block: vz.space(8) vz.space(3);
}

.select {
  padding-inline-end: vz.space(10);
  appearance: none;
  cursor: pointer;
}

.disabled .select {
  cursor: not-allowed;
}

.label {
  position: absolute;
  inset-inline-start: vz.space(3.5);
  top: 50%;
  z-index: 1;
  max-width: calc(100% - #{vz.space(7)});
  overflow: clip visible;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('base');
  font-weight: 400;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
  transform: translateY(-50%);
  transform-origin: top left;
  transition:
    top vz.duration('base') vz.ease('out'),
    transform vz.duration('base') vz.ease('out'),
    color vz.duration('base') vz.ease('out'),
    background-color vz.duration('base') vz.ease('out'),
    padding vz.duration('base') vz.ease('out');

  @include vz.motion-reduce {
    transition: none;
  }
}

.label-multiline {
  top: vz.space(3.5);
  transform: translateY(0);
}

.label-leading {
  inset-inline-start: vz.space(10);
}

.frame[data-filled='true'] .label,
.input:focus ~ .label,
.input:not(:placeholder-shown) ~ .label,
.textarea:focus ~ .label,
.textarea:not(:placeholder-shown) ~ .label,
.select:focus ~ .label {
  top: var(--label-float-top);
  transform: translateY(var(--label-float-y)) scale(0.75);
}

.input:focus ~ .label,
.textarea:focus ~ .label,
.select:focus ~ .label {
  color: vz.color('ring');
}

.frame.invalid .label {
  color: vz.color('destructive');
}

.frame.valid .label {
  color: vz.color('success');
}

.frame.outlined[data-filled='true'] .label,
.frame.outlined .input:focus ~ .label,
.frame.outlined .input:not(:placeholder-shown) ~ .label,
.frame.outlined .textarea:focus ~ .label,
.frame.outlined .textarea:not(:placeholder-shown) ~ .label,
.frame.outlined .select:focus ~ .label {
  padding-inline: vz.space(1.5);
  margin-inline-start: calc(#{vz.space(1.5)} * -1);
  background: var(--vz-float-notch, #{vz.color('background')});
}

.required {
  margin-inline-start: vz.space(0.5);
  color: vz.color('destructive');
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}

.message {
  display: flex;
  align-items: flex-start;
  gap: vz.space(1);
  margin: 0;
  font-size: vz.font-size('xs');
}

.message-icon {
  flex: none;
  width: 0.875rem;
  height: 0.875rem;
  margin-block-start: 1px;
}

.error-text {
  color: vz.color('destructive');
}

.success-text {
  color: vz.color('success');
}

.hint {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
}
